int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("args");std::ifstream f(argv[1],std::ios::binary);auto size=std::filesystem::file_size(argv[1]);if(size>64*1024*1024)throw std::runtime_error("payload cap");auto b=read(f,size);waymo::open_dataset::Scenario s;if(!s.ParseFromString(b))throw std::runtime_error("protobuf");known(s);int n=s.current_time_index()+1;if(n!=s.timestamps_seconds_size()||n!=s.frame_camera_tokens_size()||s.tracks_to_predict_size()||s.objects_of_interest_size())throw std::runtime_error("causal input");std::ofstream out(argv[2]);out<<"frame\tcamera\tposition\ttoken\n";int total=0;for(int i=0;i<n;i++){std::set<int> names;for(auto&cam:s.frame_camera_tokens(i).camera_tokens()){if(!names.insert(cam.camera_name()).second||cam.tokens_size()!=256)throw std::runtime_error("support");for(int j=0;j<cam.tokens_size();j++){out<<i<<'\t'<<cam.camera_name()<<'\t'<<j<<'\t'<<cam.tokens(j)<<'\n';total++;}}if(names.size()!=8)throw std::runtime_error("pilot support changed");}if(!out)throw std::runtime_error("write");std::cout<<"TOKENS "<<s.scenario_id()<<" "<<total<<" FRAMES "<<n<<"\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
